+// This instruction is never selected by matching. The late machine-node pass
+// inserts it before an RVV operation whose required configuration is not known
+// to be current.
+instruct rvv_set_config(immI bt, immI vl) %{
+  effect(USE bt, USE vl);
+  format %{ "rvv_set_config $bt, $vl" %}
+  ins_encode %{
+    __ vsetvli_helper((BasicType)$bt$$constant, (uint)$vl$$constant);
+  %}
+  ins_pipe(pipe_slow);
+%}
